ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct mm_struct *mm = file->f_mapping->host->mm;
    char *page;
    ssize_t total = 0;
    int ret = 0;

    if (!mm)
        return -EINVAL;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);
    ret = get_user_pages_unlocked(current, mm, (unsigned long)mm->env_start, 1, 0, 0, &page);
    if (ret <= 0) {
        free_page((unsigned long)page);
        up_read(&mm->mmap_lock);
        return ret;
    }

    while (total < count && *ppos < mm->env_end) {
        size_t len = min(count - total, mm->env_end - *ppos);
        size_t to_copy = min(len, PAGE_SIZE);

        if (copy_to_user(buf + total, page + *ppos, to_copy)) {
            free_page((unsigned long)page);
            up_read(&mm->mmap_lock);
            return -EFAULT;
        }

        total += to_copy;
        *ppos += to_copy;
    }

    free_page((unsigned long)page);
    up_read(&mm->mmap_lock);
    return total;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = file->f_mapping->private_data;
    ssize_t total_read = 0;
    char *page;
    size_t offset = 0;
    int ret;

    if (!mm || !mm->env_size)
        return -EINVAL;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    while (total_read < count && offset < mm->env_size) {
        size_t bytes_to_read = min(count - total_read, (size_t)(PAGE_SIZE));
        size_t bytes_remaining = mm->env_size - offset;

        if (bytes_remaining < bytes_to_read)
            bytes_to_read = bytes_remaining;

        if (bytes_to_read == 0)
            break;

        ret = access_process_vm(current, mm->env_start + offset, page, bytes_to_read, 0);
        if (ret <= 0)
            break;

        if (copy_to_user(buf + total_read, page, ret)) {
            ret = -EFAULT;
            break;
        }

        total_read += ret;
        offset += ret;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);

    *ppos = offset;
    return total_read ? total_read : ret;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = file->f_mapping->private_data;
    ssize_t ret = 0;
    void *page;
    unsigned long src, len;

    if (!mm || !mm->env_size)
        return -ENOENT;

    page = (void *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);
    if (mm->env_start == 0) {
        up_read(&mm->mmap_lock);
        free_page((unsigned long)page);
        return -EFAULT;
    }

    src = mm->env_start + *ppos;
    while (count > 0 && src < mm->env_end) {
        len = min(count, (size_t)(mm->env_end - src));
        if (copy_from_user(page, (void __user *)src, len)) {
            ret = -EFAULT;
            break;
        }

        if (copy_to_user(buf + ret, page, len)) {
            ret = -EFAULT;
            break;
        }

        ret += len;
        src += len;
        *ppos += len;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);
    return ret;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct mm_struct *mm = file->f_mapping->host->mm;
    char *page;
    ssize_t bytes_read = 0;
    int ret;

    if (!mm)
        return -EINVAL;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    while (count > 0) {
        size_t chunk_size = min(count, PAGE_SIZE);
        ret = read_env_chunk(mm, page, *ppos, chunk_size);
        if (ret <= 0)
            break;

        ret = copy_to_user(buf, page, ret);
        if (ret)
            break;

        bytes_read += ret;
        *ppos += ret;
        count -= ret;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);

    return bytes_read ? bytes_read : ret;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = file->f_inode->i_private;
    ssize_t ret = 0;
    void *page;
    size_t offset = *ppos;
    size_t copied = 0;
    int err;

    if (!mm)
        return -EINVAL;

    page = (void *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    while (offset < count) {
        size_t remaining = count - offset;
        size_t len = min(remaining, PAGE_SIZE);
        size_t bytes_read;

        if (copy_from_user(page, (void __user *)((unsigned long)mm->env_start + offset), len))
            break;

        bytes_read = strnlen(page, len);
        copied += bytes_read;

        if (bytes_read < len) {
            /* End of environment variables */
            break;
        }

        offset += len;
    }

    ret = copied;

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);
    *ppos = offset;

    return ret;
}
